import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    greetings = []
    idx = 1
    for i in range(n):
        greetings.append((input_data[idx], i + 1))
        idx += 1

    greetings.sort(key=lambda x: len(x[0]))

    selected = []
    selected_set = set()

    for s, original_idx in greetings:
        is_substring = False
        for t in selected_set:
            if s in t:
                is_substring = True
                break
        if not is_substring:
            is_contained = False
            for t in selected_set:
                if t in s:
                    is_contained = True
                    break
            if not is_contained:
                selected.append(original_idx)
                selected_set.add(s)

    print(len(selected))
    print(*(sorted(selected)))

if __name__ == "__main__":
    main()
